# typed: strict
# frozen_string_literal: true

# Generated by scripts/release/package_metadata.py. Do not edit.
class Devknx < Formula
  desc "KNX monitor with CLI, TUI, GUI, REST and MCP"
  homepage "https://github.com/metaneutrons/devknx"
  license "GPL-3.0-only"

  on_macos do
    depends_on arch: :arm64
    on_arm do
      url "https://github.com/metaneutrons/devknx/releases/download/v0.4.1/devknx-v0.4.1-aarch64-apple-darwin.tar.gz"
      sha256 "784563ff50357eff8a68147fabbfe2bd1aceb1d6f4d8c44de9d74bb2e2200fc3"
    end
  end

  on_linux do
    depends_on "libx11"
    depends_on "libxcb"
    depends_on "libxcursor"
    depends_on "libxi"
    depends_on "libxkbcommon"
    depends_on "mesa"
    depends_on "wayland"
    if Hardware::CPU.arm?
      url "https://github.com/metaneutrons/devknx/releases/download/v0.4.1/devknx-v0.4.1-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "3f5354afad2a4324b18654794974eb693c7d36846e6016969017ecf844400bd1"
    else
      url "https://github.com/metaneutrons/devknx/releases/download/v0.4.1/devknx-v0.4.1-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "e3fc9fa4937211772229dccf6a7145fca77ec82439bd6d0e302a3ea4c6362f97"
    end
  end

  def install
    root = Dir["devknx", "devknx-v*-*/devknx"].find { |path| File.file?(path) }
    raise "missing devknx executable" unless root

    if OS.linux?
      libexec.install root
      gui_libraries = %w[
        libx11 libxcb libxcursor libxi libxkbcommon mesa wayland
      ].map { |name| formula_opt_lib(name) }
      loader_path = "#{gui_libraries.join(":")}${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
      bin.join("devknx").write_env_script libexec/"devknx", LD_LIBRARY_PATH: loader_path
    else
      bin.install root
    end
    source_root = File.dirname(root)
    doc.install File.join(source_root, "THIRD-PARTY-NOTICES.md")
    doc.install File.join(source_root, "licenses")
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/devknx --version")
  end
end
